<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --panel-strong: #1f2937;
      --text: #f8fafc;
      --muted: #9ca3af;
      --accent: #7c3aed;
      --accent-light: #a78bfa;
      --danger: #fb7185;
      --border: #30363d;
      --focus: rgba(167, 139, 250, 0.32);
      --shadow: rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px 18px;
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.3), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 28rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    .support-card {
      width: min(100%, 520px);
      padding: 34px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      background: linear-gradient(145deg, rgba(22, 27, 34, 0.96), rgba(17, 24, 39, 0.94));
      box-shadow: 0 24px 70px var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent-light);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 7vw, 3rem);
      line-height: 1.05;
    }

    .intro {
      margin: 14px 0 28px;
      color: var(--muted);
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      font-weight: 700;
    }

    input {
      width: 100%;
      min-height: 50px;
      padding: 13px 14px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(13, 17, 23, 0.76);
      color: var(--text);
      font: inherit;
      outline: none;
      transition: border-color 150ms ease, box-shadow 150ms ease, background 150ms ease;
    }

    input::placeholder {
      color: #6b7280;
    }

    input:focus {
      border-color: var(--accent-light);
      box-shadow: 0 0 0 4px var(--focus);
      background: rgba(15, 23, 42, 0.9);
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
    }

    .helper-text,
    .error-message {
      margin: 7px 2px 0;
      font-size: 0.9rem;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      color: var(--danger);
      font-weight: 650;
    }

    button {
      width: 100%;
      min-height: 52px;
      margin-top: 6px;
      border: 0;
      border-radius: 16px;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      letter-spacing: 0.01em;
      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.25);
      transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.08);
      box-shadow: 0 22px 42px rgba(37, 99, 235, 0.32);
    }

    button:focus-visible {
      outline: 4px solid var(--focus);
      outline-offset: 3px;
    }

    .success-message {
      margin: 18px 0 0;
      padding: 12px 14px;
      border: 1px solid rgba(52, 211, 153, 0.35);
      border-radius: 14px;
      background: rgba(6, 95, 70, 0.22);
      color: #86efac;
      font-weight: 650;
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Alex Morgan",
        required: true,
        autocomplete: "name"
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        placeholder: "alex@example.com",
        required: true,
        autocomplete: "email"
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        autocomplete: "tel",
        helperText: "Expected format: +1 555 123 4567 or 555-123-4567."
      }
    ];

    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      errors: {},
      submitted: false
    };

    function validate(values) {
      const errors = {};
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[\d\s().-]{7,20}$/;

      if (!values.fullName.trim()) {
        errors.fullName = "Full name is required.";
      }

      if (!values.email.trim()) {
        errors.email = "Email address is required.";
      } else if (!emailPattern.test(values.email.trim())) {
        errors.email = "Enter a valid email address.";
      }

      if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
        errors.phone = "Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign.";
      }

      return errors;
    }

    function FormField({ id, label, type, placeholder, required, autocomplete, helperText }) {
      const error = state.errors[id];
      const describedBy = [
        helperText ? `${id}-helper` : "",
        error ? `${id}-error` : ""
      ].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? " *" : ""}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${placeholder}"
            value="${escapeHtml(state.values[id])}"
            autocomplete="${autocomplete}"
            ${required ? "required" : ""}
            aria-invalid="${error ? "true" : "false"}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          >
          ${helperText ? `<p class="helper-text" id="${id}-helper">${helperText}</p>` : ""}
          ${error ? `<p class="error-message" id="${id}-error">${error}</p>` : ""}
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">How can we help?</h1>
          <p class="intro">Send our team your contact details and we will get back to you shortly.</p>

          <form novalidate>
            ${fields.map(FormField).join("")}
            <button type="submit">Contact support</button>
          </form>

          ${state.submitted ? '<p class="success-message" role="status">Thanks. Your support request contact details are ready to send.</p>' : ""}
        </section>
      `;
    }

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll('"', "&quot;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;");
    }

    function render() {
      const app = document.querySelector("#app");
      app.innerHTML = ContactForm();

      app.querySelectorAll("input").forEach((input) => {
        input.addEventListener("input", (event) => {
          state.values[event.target.name] = event.target.value;
          state.errors = validate(state.values);
          state.submitted = false;
          render();
          document.querySelector(`#${event.target.id}`).focus();
        });
      });

      app.querySelector("form").addEventListener("submit", (event) => {
        event.preventDefault();
        state.errors = validate(state.values);
        state.submitted = Object.keys(state.errors).length === 0;
        render();
      });
    }

    render();
  </script>
</body>
</html>
